using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Text;
using System.Linq;

namespace RcsMap {
 public static class Exporter {
  public const string Banner="/* Generated by RCS Map Editor 0.2.0. */\n";
  static string F(double v){if(!MapDocument.Finite(v))throw new Exception("非有限数值不能导出。");string t=v.ToString("G9",CultureInfo.InvariantCulture);if(t.IndexOf('.')<0&&t.IndexOf('E')<0&&t.IndexOf('e')<0)t+=".0";return t+"f";}
  public static string Resource(string name){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("assets/"+name)){if(s==null)throw new Exception("资源缺失："+name);using(var r=new StreamReader(s,Encoding.UTF8))return r.ReadToEnd();}}
  public static Dictionary<string,string> Generate(MapDocument d) {
   var errors=d.Validate();if(errors.Count>0)throw new Exception(String.Join("\r\n",errors.ToArray()));
   var s=d.Settings;var b=new StringBuilder(Banner);
   b.Append("#include \"rcs_route.h\"\n\nconst rcs_nav_config rcs_route_config = {\n { (rcs_layout)").Append(s.Layout).Append(", ")
    .Append(F(s.Diameter/1000)).Append(", ").Append(F(s.Wheelbase/1000)).Append(", ").Append(F(s.Track/1000)).Append(", ")
    .Append(F(s.OmniRadius/1000)).Append(", ").Append(F(s.Theta0*Math.PI/180)).Append(", ").Append(F(s.Gear)).Append(", ").Append(F(s.MaxRpm)).Append(" },\n ")
    .Append(F(s.Cpr)).Append(", {").Append(String.Join(",",s.Directions)).Append("},\n ")
    .Append(F(s.MaxSpeed/1000)).Append(", ").Append(F(s.MaxWz*Math.PI/180)).Append(", ").Append(F(s.Accel/1000)).Append(", ").Append(F(s.Alpha*Math.PI/180)).Append(",\n ")
    .Append(F(s.PositionKp)).Append(", ").Append(F(s.YawKp)).Append(", ").Append(F(s.PositionTolerance/1000)).Append(", ").Append(F(s.YawTolerance*Math.PI/180)).Append(",\n ")
    .Append(F(s.MaxDtMs/1000)).Append(", ").Append(F(s.LegTimeout)).Append(", ").Append(d.Points.Any(p=>p.ActionEnabled)?"1u":"0u").Append("\n};\n\nconst rcs_waypoint rcs_route_points[RCS_ROUTE_POINT_COUNT] = {\n");
   foreach(var p in d.Points)b.Append(" { ").Append(F(p.X/1000)).Append(", ").Append(F(p.Y/1000)).Append(", ").Append(F(p.Yaw*Math.PI/180)).Append(", ").Append(F(p.Speed/1000)).Append(", ").Append(F(p.Dwell)).Append(" },\n");
   b.Append("};\n\n/* Integrated ideal count references; runtime tracks pose, NOT these totals.\n * Time estimate excludes acceleration, settling and dwell. */\nconst rcs_segment rcs_route_segments[RCS_ROUTE_SEGMENT_COUNT] = {\n");
   for(int i=1;i<d.Points.Count;i++){var a=SegmentInfo.Calculate(s,d.Points[i-1],d.Points[i],i-1);b.Append(" { ").Append(F(a.Distance)).Append(", ").Append(F(a.Turn)).Append(", ").Append(F(a.Seconds)).Append(", {");for(int j=0;j<4;j++){if(j>0)b.Append(", ");b.Append(F(a.Counts[j]));}b.Append("} },\n");}
   b.Append("};\n\n#include \"rcs_actions.h\"\nint rcs_route_init(rcs_navigator *n,void *action_context) {\n if(!rcs_nav_init(n,&rcs_route_config,rcs_route_points,RCS_ROUTE_POINT_COUNT)) return 0;\n return rcs_nav_bind_actions(n,rcs_route_actions,RCS_ROUTE_POINT_COUNT,rcs_route_action,action_context);\n}\n");
   string h=Banner+"#ifndef RCS_ROUTE_H\n#define RCS_ROUTE_H\n#include \"rcs_nav.h\"\n#ifdef __cplusplus\nextern \"C\" {\n#endif\n#define RCS_ROUTE_POINT_COUNT "+d.Points.Count+"u\n#define RCS_ROUTE_SEGMENT_COUNT "+(d.Points.Count-1)+"u\nextern const rcs_nav_config rcs_route_config;\nextern const rcs_waypoint rcs_route_points[RCS_ROUTE_POINT_COUNT];\nextern const rcs_segment rcs_route_segments[RCS_ROUTE_SEGMENT_COUNT];\n/* Initializes navigation AND waypoint actions; no motor activation. */\nint rcs_route_init(rcs_navigator *n,void *action_context);\n#ifdef __cplusplus\n}\n#endif\n#endif\n";
   var files=new Dictionary<string,string>{{"rcs_route.c",b.ToString()},{"rcs_route.h",h},{"rcs_nav.c",Resource("rcs_nav.c")},{"rcs_nav.h",Resource("rcs_nav.h")},{"rcs_actions.c",Actions(d)},{"rcs_actions.h",ActionsHeader()}};
   return files.ToDictionary(f=>f.Key,f=>UserRegions.Seal(f.Value));
  }
  static string ActionsHeader(){return Banner+"#ifndef RCS_ACTIONS_H\n#define RCS_ACTIONS_H\n#include \"rcs_route.h\"\n#ifdef __cplusplus\nextern \"C\" {\n#endif\nextern const rcs_action_spec rcs_route_actions[RCS_ROUTE_POINT_COUNT];\nrcs_action_result rcs_route_action(void *context,size_t point,rcs_action_phase phase,float elapsed_s);\n#ifdef __cplusplus\n}\n#endif\n#endif\n";}
  static string Actions(MapDocument d){var b=new StringBuilder(Banner+"#include \"rcs_actions.h\"\n\n/* Edit USER CODE regions only. Non-blocking callbacks; no HAL_Delay. */\n");
   b.Append(UserRegions.Block("RCS_ACTION_INCLUDES",d.ActionIncludes));b.Append(UserRegions.Block("RCS_ACTION_GLOBALS","/* Shared state or your action_context type. */"));
   b.Append("\nconst rcs_action_spec rcs_route_actions[RCS_ROUTE_POINT_COUNT] = {\n");foreach(var p in d.Points)b.Append(" { ").Append(p.ActionEnabled?"1u":"0u").Append(", ").Append(F(p.ActionTimeout)).Append(" },\n");b.Append("};\n");
   for(int i=0;i<d.Points.Count;i++){var p=d.Points[i];string id=p.Id.ToLowerInvariant(),key="WP_"+id.ToUpperInvariant();
    string name=(p.ActionName??"").Replace("*/","* /").Replace("\r"," ").Replace("\n"," ");
    b.Append("\n/* P").Append(i).Append(" : ").Append(name).Append(". Stable waypoint ID: ").Append(id).Append(" */\nstatic rcs_action_result action_").Append(id).Append("(void *context,rcs_action_phase phase,float elapsed_s) {\n int complete=0;\n (void)context; (void)elapsed_s;\n if(phase==RCS_ACTION_CANCEL) {\n").Append(UserRegions.Block(key+"_CANCEL",p.ActionCancel)).Append("  return RCS_ACTION_DONE;\n }\n if(phase==RCS_ACTION_ENTER) {\n").Append(UserRegions.Block(key+"_ENTER",p.ActionStart)).Append("  return RCS_ACTION_BUSY;\n }\n");
    string expr=String.IsNullOrWhiteSpace(p.ActionCondition)?"1":p.ActionCondition;
    b.Append(UserRegions.Block(key+"_POLL","/* Set complete, or return RCS_ACTION_ERROR for a mechanism fault. */\n complete = ("+expr+") ? 1 : 0;")).Append(" if(complete) {\n").Append(UserRegions.Block(key+"_DONE",p.ActionDone)).Append("  return RCS_ACTION_DONE;\n }\n return RCS_ACTION_BUSY;\n}\n");
   }
   b.Append("\nrcs_action_result rcs_route_action(void *context,size_t point,rcs_action_phase phase,float elapsed_s) {\n switch(point) {\n");for(int i=0;i<d.Points.Count;i++)b.Append(" case ").Append(i).Append("u: return action_").Append(d.Points[i].Id.ToLowerInvariant()).Append("(context,phase,elapsed_s);\n");
   return b.Append(" default: return RCS_ACTION_ERROR;\n }\n}\n").ToString();
  }
  // Own checksummed generated files only; USER CODE is merged by stable waypoint ID.
  public static void Export(MapDocument d,string dir) {
   var files=Generate(d);dir=Path.GetFullPath(dir);
   bool existing=Directory.Exists(dir)&&Directory.GetFileSystemEntries(dir).Length>0;
   if(existing){var names=Directory.GetFileSystemEntries(dir).Select(Path.GetFileName).OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(!names.SequenceEqual(files.Keys.OrderBy(x=>x,StringComparer.Ordinal)))throw new Exception("目录含非本版生成文件，保留原内容。请选择新目录。");
    foreach(string name in files.Keys.ToArray())files[name]=UserRegions.Merge(File.ReadAllText(Path.Combine(dir,name)),files[name]);}
   string parent=Path.GetDirectoryName(dir);Directory.CreateDirectory(parent);string temp=Path.Combine(parent,".rcs-export-"+Guid.NewGuid().ToString("N"));
   string backup=Path.Combine(parent,".rcs-route-backup-"+Guid.NewGuid().ToString("N"));
   Directory.CreateDirectory(temp);try{foreach(var f in files)File.WriteAllText(Path.Combine(temp,f.Key),f.Value,new UTF8Encoding(false));if(existing)Directory.Move(dir,backup);else if(Directory.Exists(dir))Directory.Delete(dir);
    try{Directory.Move(temp,dir);}catch(Exception installError){if(existing&&Directory.Exists(backup)){try{if(!Directory.Exists(dir))Directory.Move(backup,dir);else throw new IOException("目标目录已被其他进程创建。");}catch(Exception restoreError){throw new IOException("更新失败，原文件仍保存在："+backup+"。恢复错误："+restoreError.Message,installError);}}throw;}
   }finally{if(Directory.Exists(temp))Directory.Delete(temp,true);}
  }
 }
}
